const rows = $input.all().map(i => i.json).filter(r => r && r.experiment_id);
const syms = new Set(['SPY']);
let earliest = Date.now();
for (const r of rows) {
  if (r.asset) syms.add(String(r.asset).toUpperCase());
  if (r.benchmark) syms.add(String(r.benchmark).toUpperCase());
  const t = Date.parse(r.decided_at || r.proposed_at || r.createdAt || '');
  if (!isNaN(t) && t < earliest) earliest = t;
}
const floor = Date.now() - 365 * 86400000;
const start = new Date(Math.max(floor, earliest - 60 * 86400000)).toISOString().slice(0, 10);
return [{ json: { symbols: Array.from(syms).join(','), start: start, count: rows.length } }];

const rows = $('Load Experiments').all().map(i => i.json).filter(r => r && r.experiment_id);
const resp = $input.first().json || {};
const bars = resp.bars || {};
const priceError = !resp.bars;

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function pct(x) {
  if (x == null || isNaN(x)) return 'n/a';
  return (x >= 0 ? '+' : '') + (x * 100).toFixed(2) + '%';
}
function money(x) {
  const n = Number(x);
  if (!n) return '$0';
  return '$' + n.toLocaleString('en-US', { maximumFractionDigits: 0 });
}
function day(s) {
  if (!s) return '';
  const t = Date.parse(s);
  if (isNaN(t)) return '';
  return new Date(t).toISOString().slice(0, 10);
}
function cleanThesis(s) {
  let t = String(s || '');
  const cut = t.search(/\n\s*--|\n\s*(Best|Thanks|Regards|Cheers|Sent from)\b/i);
  if (cut > 0) t = t.slice(0, cut);
  return t.replace(/\s+/g, ' ').trim();
}
function series(sym) {
  return (bars[sym] || []).map(b => ({ d: String(b.t).slice(0, 10), c: Number(b.c) })).filter(b => b.c > 0);
}

function verdictLabel(v) {
  const s = String(v || '');
  const early = s.indexOf('interim_') === 0;
  const base = early ? s.slice(8) : s;
  const m = { supported: 'Held up', rejected: "Didn't hold up", inconclusive: 'Too close to call' };
  return m[base] ? (early ? 'Early read: ' : '') + m[base] : s;
}
function row(label, text) {
  return text ? '<p class="claim"><b>' + label + ':</b> ' + esc(text) + '</p>' : '';
}

const COLORS = { proposed: '#f5b942', approved: '#3ddc97', evaluated: '#5aa9ff', closed: '#9b8cff', rejected: '#ff6b6b' };

function chart(a, b, startDay, assetSym, benchSym) {
  if (!a.length || !b.length) return '<div class="nochart">No price data available</div>';
  const bMap = {};
  for (const x of b) bMap[x.d] = x.c;
  const pts = a.filter(x => bMap[x.d] != null).map(x => ({ d: x.d, a: x.c, b: bMap[x.d] }));
  if (pts.length < 2) return '<div class="nochart">Not enough overlapping price data</div>';
  let si = 0;
  for (let i = 0; i < pts.length; i++) { if (pts[i].d <= startDay) si = i; }
  const from = Math.max(0, si - 40);
  const view = pts.slice(from);
  const s0 = pts[si];
  const ra = view.map(p => p.a / s0.a - 1);
  const rb = view.map(p => p.b / s0.b - 1);
  const all = ra.concat(rb, [0]);
  let lo = Math.min.apply(null, all), hi = Math.max.apply(null, all);
  if (hi - lo < 0.02) { hi += 0.01; lo -= 0.01; }
  const W = 560, H = 190, P = 28;
  const n = view.length;
  const X = i => P + (n === 1 ? 0 : (i * (W - 2 * P)) / (n - 1));
  const Y = v => H - P - ((v - lo) * (H - 2 * P)) / (hi - lo);
  const path = arr => arr.map((v, i) => (i ? 'L' : 'M') + X(i).toFixed(1) + ',' + Y(v).toFixed(1)).join(' ');
  const mi = si - from;
  const area = path(ra) + ' L' + X(n - 1).toFixed(1) + ',' + Y(0).toFixed(1) + ' L' + X(0).toFixed(1) + ',' + Y(0).toFixed(1) + ' Z';
  let svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" class="chart">';
  svg += '<line x1="' + P + '" x2="' + (W - P) + '" y1="' + Y(0) + '" y2="' + Y(0) + '" class="zero"/>';
  svg += '<path d="' + area + '" class="area"/>';
  svg += '<path d="' + path(rb) + '" class="bench"/>';
  svg += '<path d="' + path(ra) + '" class="asset"/>';
  svg += '<line x1="' + X(mi) + '" x2="' + X(mi) + '" y1="' + (P - 8) + '" y2="' + (H - P) + '" class="marker"/>';
  svg += '<text x="' + (X(mi) + 4) + '" y="' + (P - 10) + '" class="lbl">bet placed</text>';
  svg += '<circle cx="' + X(n - 1) + '" cy="' + Y(ra[n - 1]) + '" r="4" class="dot"/>';
  svg += '<text x="' + (W - P) + '" y="' + (H - 6) + '" class="lbl" text-anchor="end">' + esc(view[n - 1].d) + '</text>';
  svg += '<text x="' + P + '" y="' + (H - 6) + '" class="lbl">' + esc(view[0].d) + '</text>';
  svg += '<text x="4" y="' + (Y(hi) + 4) + '" class="lbl">' + pct(hi) + '</text>';
  svg += '<text x="4" y="' + (Y(lo) + 4) + '" class="lbl">' + pct(lo) + '</text>';
  svg += '</svg>';
  const last = pts[pts.length - 1];
  return {
    svg: svg,
    assetRet: last.a / s0.a - 1,
    benchRet: last.b / s0.b - 1,
    elapsed: pts.length - 1 - si,
    asOf: last.d,
    legend: '<div class="legend"><span class="la">' + esc(assetSym) + '</span><span class="lb">' + esc(benchSym) + '</span><span class="muted">return rebased to the bet date</span></div>',
  };
}

let active = 0, proposed = 0, done = 0, rejected = 0, deployed = 0;
const cards = [];
for (const r of rows) {
  const st = String(r.status || 'proposed').toLowerCase();
  if (st === 'approved') { active++; deployed += Number(r.notional_usd) || 0; }
  else if (st === 'proposed') proposed++;
  else if (st === 'rejected') rejected++;
  else done++;
  const asset = String(r.asset || '').toUpperCase();
  const bench = String(r.benchmark || 'SPY').toUpperCase();
  const startDay = day(r.decided_at) || day(r.proposed_at) || day(r.createdAt);
  const c = chart(series(asset), series(bench), startDay, asset, bench);
  let verdict = '';
  if (r.outcome) {
    try { const o = JSON.parse(r.outcome); verdict = o.verdict_label || verdictLabel(o.verdict); } catch (e) { verdict = ''; }
  }
  let sj = {};
  try { sj = JSON.parse(r.strategy_json || '{}') || {}; } catch (e) { sj = {}; }
  const risks = Array.isArray(sj.risk_warnings) ? sj.risk_warnings : [];
  const shortText = (t) => { const parts = String(t || '').match(/[^.!?]+[.!?]+/g) || [String(t || '')]; return parts.slice(0, 2).join(' ').trim(); };
  const reason = sj.reason || shortText(sj.rationale);
  const realRisks = risks.filter(x => !/paper trading|no live/i.test(String(x)));
  const risk = sj.main_risk || realRisks[0] || '';
  const claimText = String(r.falsifiable_claim || '');
  const measuredInline = /close-to-close/i.test(claimText);
  const wrong = sj.invalidation_rule || '';
  const color = COLORS[st] || '#aaa';
  let stats = '';
  let svg = typeof c === 'string' ? c : c.svg;
  if (typeof c !== 'string') {
    const alpha = c.assetRet - c.benchRet;
    const horizon = Number(r.horizon_days) || 0;
    const prog = horizon ? Math.min(1, Math.max(0, c.elapsed / horizon)) : 0;
    const winning = alpha >= 0;
    const tag = st === 'proposed' ? 'hypothetical since proposal' : 'since entry';
    stats += '<div class="stats">';
    stats += '<div><div class="k">' + esc(asset) + '</div><div class="v">' + pct(c.assetRet) + '</div></div>';
    stats += '<div><div class="k">' + esc(bench) + '</div><div class="v">' + pct(c.benchRet) + '</div></div>';
    stats += '<div><div class="k">Edge vs benchmark</div><div class="v ' + (winning ? 'up' : 'down') + '">' + pct(alpha) + '</div></div>';
    stats += '<div><div class="k">Paper size</div><div class="v">' + money(r.notional_usd) + '</div></div>';
    stats += '</div>';
    stats += '<div class="muted small">' + tag + ', as of close ' + esc(c.asOf) + '</div>';
    if (horizon) {
      stats += '<div class="prog"><div class="bar" style="width:' + (prog * 100).toFixed(0) + '%;background:' + color + '"></div></div>';
      stats += '<div class="muted small">' + Math.min(c.elapsed, horizon) + ' of ' + horizon + ' trading days</div>';
    }
    svg = c.legend + svg;
  }
  let card = '<article class="card" style="--c:' + color + '">';
  card += '<header><div><span class="tick">' + esc(asset) + '</span><span class="vs"> vs ' + esc(bench) + '</span></div>';
  card += '<span class="pill">' + esc(st) + (verdict ? ' &middot; ' + esc(verdict) : '') + '</span></header>';
  card += '<p class="thesis">&ldquo;' + esc(cleanThesis(r.thesis)) + '&rdquo;</p>';
  card += svg + stats;
  card += '<div class="bet">';
  card += row('The Bet', r.falsifiable_claim);
  if (!measuredInline) card += '<p class="muted small">Measured by close-to-close total return.</p>';
  card += row('The Reason', reason);
  card += row('The Risk', risk);
  card += row('What Would Prove Us Wrong', wrong);
  card += row('The Verdict', verdict || (st === 'rejected' ? 'Not pursued' : 'Pending, the test is still running'));
  card += '</div>';
  card += '<footer><span>' + esc(r.experiment_id) + '</span><span>proposed ' + esc(day(r.proposed_at)) + '</span></footer>';
  card += '</article>';
  cards.push(card);
}

const updated = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', dateStyle: 'medium', timeStyle: 'short' });
const css = 'body{margin:0;background:#0b0f17;color:#e6e9ef;font-family:Inter,-apple-system,Segoe UI,Roboto,sans-serif}'
 + '.wrap{max-width:1280px;margin:0 auto;padding:32px 24px}'
 + 'h1{margin:0;font-size:30px;letter-spacing:-0.5px}h1 span{color:#3ddc97}'
 + '.sub{color:#8a93a6;margin:6px 0 24px}'
 + '.kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin-bottom:28px}'
 + '.kpi{background:#121826;border:1px solid #1f2738;border-radius:14px;padding:16px}.kpi .n{font-size:26px;font-weight:700}.kpi .l{color:#8a93a6;font-size:12px;text-transform:uppercase;letter-spacing:1px}'
 + '.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(560px,1fr));gap:18px}'
 + '.card{background:linear-gradient(180deg,#131a2a,#0f1420);border:1px solid #1f2738;border-top:3px solid var(--c);border-radius:16px;padding:18px 20px}'
 + '.card header{display:flex;justify-content:space-between;align-items:center}'
 + '.tick{font-size:24px;font-weight:800}.vs{color:#8a93a6}'
 + '.pill{background:color-mix(in srgb,var(--c) 18%,transparent);color:var(--c);padding:4px 10px;border-radius:99px;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:1px}'
 + '.thesis{font-size:16px;color:#cfd5e1;margin:10px 0}'
 + '.chart{width:100%;height:auto}.zero{stroke:#2a3346;stroke-dasharray:4 4}.asset{fill:none;stroke:var(--c);stroke-width:2.5}.bench{fill:none;stroke:#6b7489;stroke-width:1.8;stroke-dasharray:5 3}'
 + '.area{fill:var(--c);opacity:.08}.marker{stroke:#e6e9ef;stroke-opacity:.35;stroke-dasharray:2 3}.dot{fill:var(--c)}.lbl{fill:#6b7489;font-size:10px}'
 + '.legend{display:flex;gap:14px;font-size:12px;margin-top:6px}.la{color:var(--c);font-weight:700;border-bottom:3px solid var(--c)}.lb{color:#8a93a6;border-bottom:2px dashed #6b7489}'
 + '.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:6px}.k{color:#8a93a6;font-size:11px;text-transform:uppercase}.v{font-size:18px;font-weight:700}.up{color:#3ddc97}.down{color:#ff6b6b}'
 + '.prog{height:6px;background:#1f2738;border-radius:9px;margin:10px 0 4px;overflow:hidden}.bar{height:100%}'
 + '.claim{font-size:13px;color:#aab2c3;margin:6px 0}.claim b{color:#e6e9ef}.bet{margin:12px 0 8px}.muted{color:#6b7489}.small{font-size:12px}'
 + '.card footer{display:flex;justify-content:space-between;color:#6b7489;font-size:12px;border-top:1px solid #1f2738;padding-top:8px}'
 + '.nochart{padding:40px;text-align:center;color:#6b7489;border:1px dashed #1f2738;border-radius:10px;margin:10px 0}'
 + '.warn{background:#3a2a10;color:#f5b942;padding:10px 14px;border-radius:10px;margin-bottom:16px}'
 + '.empty{padding:60px;text-align:center;color:#8a93a6}'
 + '@media(max-width:700px){.kpis{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}}';

let html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">';
html += '<meta http-equiv="refresh" content="60"><title>ThesisLab Board</title><style>' + css + '</style></head><body><div class="wrap">';
html += '<h1>ThesisLab <span>Board</span></h1>';
html += '<div class="sub">Every thesis is a falsifiable experiment. Paper trading only. Updated ' + esc(updated) + ' ET, refreshes every 60s.</div>';
if (priceError) html += '<div class="warn">Market data is unavailable right now, so charts are hidden. No prices are shown rather than guessed.</div>';
html += '<div class="kpis">';
html += '<div class="kpi"><div class="n">' + rows.length + '</div><div class="l">Theses</div></div>';
html += '<div class="kpi"><div class="n" style="color:#3ddc97">' + active + '</div><div class="l">Live bets</div></div>';
html += '<div class="kpi"><div class="n" style="color:#f5b942">' + proposed + '</div><div class="l">Awaiting approval</div></div>';
html += '<div class="kpi"><div class="n" style="color:#9b8cff">' + done + '</div><div class="l">Evaluated / closed</div></div>';
html += '<div class="kpi"><div class="n">' + money(deployed) + '</div><div class="l">Paper capital at work</div></div>';
html += '</div>';
html += cards.length ? '<div class="grid">' + cards.join('') + '</div>' : '<div class="empty">No theses yet. Send one to Arthur by email or Telegram.</div>';
html += '</div></body></html>';
return [{ json: { html: html } }];
